// ---------------------------------------------------------------------------
// Core building blocks
// ---------------------------------------------------------------------------

/** Camera intrinsics for a single frame: [fx, fy, cx, cy]. */
export type Intrinsics = [number, number, number, number];

/** 3D position [x, y, z] in meters. */
export type Vec3 = [number, number, number];

/** Quaternion [x, y, z, w]. */
export type Quat = [number, number, number, number];

/** Camera pose in the WebXR session reference space. */
export interface Pose {
  p: Vec3;
  q: Quat;
}

// ---------------------------------------------------------------------------
// DetectionRecord (§7.4)
// ---------------------------------------------------------------------------

export interface DetectionRecord {
  ledId: number;
  /** Phone monotonic clock at frame capture, in milliseconds. */
  tCaptureMs: number;
  /** Sub-pixel centroid x (origin top-left). */
  u: number;
  /** Sub-pixel centroid y (origin top-left). */
  v: number;
  imgW: number;
  imgH: number;
  K: Intrinsics;
  /** Camera pose, or null on the WebXR-free capture path (the
   * visual-inertial reconstructor solves poses jointly; the session
   * must then carry imu_batch samples). */
  pose: Pose | null;
  /** Decoder confidence in [0, 1]. */
  confidence: number;
}

// ---------------------------------------------------------------------------
// CodeParams (§7.6)
// ---------------------------------------------------------------------------

export type Encoding = "hue";
export type SyncPattern = "on_off";
export type Fec = "none" | "secded";

export interface CodeParams {
  ledCount: number;
  /** Coded BITS per cycle: ceil(log2(ledCount+1)) data bits + FEC parity bits;
   * transmitted log2(symbols) at a time. */
  bits: number;
  encoding: Encoding;
  /** Data-symbol alphabet size (log2(symbols) bits per data frame):
   * 2 = red/blue, 4 = blue/magenta/red/yellow carrying Gray-ordered
   * bit pairs. Negotiated by the client from measured chroma SNR. */
  symbols: number;
  /** Hold time per frame (symbol window), in milliseconds. */
  bitPeriodMs: number;
  syncPattern: SyncPattern;
  /** 2 (sync delimiter) + ceil(bits / log2(symbols)) data frames */
  cycleFrames: number;
  /** FEC around the Gray data word ('secded' = extended Hamming, d=4:
   * correct 1 misread bit, detect-and-reject 2). Absent = 'none'. */
  fec?: Fec | undefined;
  /** LED output brightness scale in [0,1]; absent = 1.0. Servoed by the
   * phone against measured bloom/wash-out (planLedBrightness). */
  brightness?: number | undefined;
  /** Diffuse-capture striding (stride_lit; web/src/code/stride.ts). absent/<=1
   * = every LED lit (legacy); else only the stridePhase subset lights, and
   * the phone rotates the phase across epochs. Echoes what the device drives. */
  strideSpacing?: number | undefined;
  anchorDensity?: number | undefined;
  stridePhase?: number | undefined;
}

// ---------------------------------------------------------------------------
// OutputMap (§7.5)
// ---------------------------------------------------------------------------

export interface LedEntry {
  id: number;
  xyz: Vec3;
  confidence: number;
  nViews: number;
  rmsReprojPx: number;
  parallaxDeg: number;
}

export interface OutputMapStats {
  rmsReprojPxGlobal: number;
  medianParallaxDeg: number;
}

export interface OutputMap {
  mapId: string;
  /** ISO-8601 timestamp. */
  createdAt: string;
  units: "meters";
  frame: "webxr_session_ref" | "gravity_leveled";
  ledCount: number;
  leds: LedEntry[];
  unmapped: number[];
  /** Solved camera path (decimated, chronological) — present for
   * visual-inertial solves; same frame as leds. */
  trajectory?: Vec3[] | undefined;
  stats: OutputMapStats;
}

// ---------------------------------------------------------------------------
// Topology (§7.7) — skeletonized fixture, uploaded alongside a map
// ---------------------------------------------------------------------------

export interface BranchPoint {
  id: number;
  /** Position in meters, same frame as the OutputMap. */
  xyz: Vec3;
}

export interface TopologySegment {
  id: number;
  /** Branch-point id at the segment start (arclength 0); -1 = free end. */
  a: number;
  /** Branch-point id at the segment end; -1 = free end. */
  b: number;
  /** Polyline from a to b; arclength is measured along it from a. */
  polyline: Vec3[];
  /** Total polyline arclength, meters. */
  length: number;
}

export interface LedAssociation {
  ledId: number;
  segmentId: number;
  /** Arclength of the LED's foot point along the segment, meters from a. */
  footArclength: number;
  /** Perpendicular distance LED -> foot point, meters. */
  dPerp: number;
}

/** Skeletonized fixture topology (Phase F output): drives the O(N)
 * pulse illuminate on players. Keyed to the OutputMap it skeletonizes. */
export interface Topology {
  mapId: string;
  branchPoints: BranchPoint[];
  segments: TopologySegment[];
  associations: LedAssociation[];
}

// ---------------------------------------------------------------------------
// PlaybackParams (§7.8) — effect tunables (pulse reference controls)
// ---------------------------------------------------------------------------

/** All fields are optional overlays: unset keeps the player's current or
 * default value, so a UI can send just the slider that moved. */
export interface PlaybackParams {
  /** Global output brightness scale in [0,1]. */
  intensity?: number | null;
  /** Soft-falloff radius around a pulse agent, meters ('soft'). */
  glowRadius?: number | null;
  /** Concurrent pulse agents traversing the topology. */
  agentCount?: number | null;
  /** Agent travel speed along the topology, m/s. */
  speed?: number | null;
  /** Palette as 0xRRGGBB ints; empty/omitted keeps the player default. */
  palette?: number[];
  /** Pulse lead-in/out ramp distance at termini, m (0/omitted derives from glow). */
  leadIn?: number | null;
  /** Probability [0,1] a pulse splits at a junction. */
  splitProb?: number | null;
  /** Flood fade length behind the wavefront, m (0/omitted derives from glow). */
  decay?: number | null;
}

// ---------------------------------------------------------------------------
// Client -> Server messages (§7.1)
// ---------------------------------------------------------------------------

export interface HelloMessage {
  type: "hello";
  client: string;
  appVersion: string;
}

export interface TimeSyncPingMessage {
  type: "time_sync_ping";
  /** Phone clock at send, in milliseconds. */
  t0: number;
}

/** The client is the configuration authority: it measured the scene, so it
 * chooses the symbol alphabet and signaling rate; omitted fields fall back
 * to server defaults. */
export interface StartMappingOptions {
  ledCount: number;
  /** Symbol alphabet size, chosen from measured chroma SNR: good -> 4, marginal -> 2. */
  symbols?: number;
  /** Signaling rate: each symbol window should span >= ~3 camera frame intervals. */
  bitPeriodMs?: number;
  /** LED output brightness scale in [0,1]; omitted -> server default 1.0. */
  brightness?: number;
  /** Diffuse-capture striding (see CodeParams). omitted/<=1 = legacy all-lit;
   * anchorDensity (>=3, default 3) sets the fusion overlap, stridePhase (default
   * 0) the initial phase the phone advances via Configure. */
  strideSpacing?: number;
  anchorDensity?: number;
  stridePhase?: number;
}

export interface StartMappingMessage {
  type: "start_mapping";
  options: StartMappingOptions;
}

/** Mid-capture renegotiation: overlay these on the active capture's params,
 * restamp the pattern epoch, keep collected detections. Reply: pattern_state. */
export interface ConfigureOptions {
  ledCount?: number;
  symbols?: number;
  bitPeriodMs?: number;
  /** LED output brightness scale in [0,1]; omitted -> keep current. */
  brightness?: number;
  /** Diffuse-capture striding (see StartMappingOptions); re-sent each epoch to
   * ADVANCE the phase (omitted fields keep the active values). */
  strideSpacing?: number;
  anchorDensity?: number;
  stridePhase?: number;
}

export interface ConfigureMessage {
  type: "configure";
  options: ConfigureOptions;
}

export interface StopMappingMessage {
  type: "stop_mapping";
  /** Solver placement (client benchmark decision): true/omitted -> the
   * server reconstructs and replies result_ready; false -> the server only
   * stops + persists (reply: mapping_stopped) and the client solves
   * locally, uploading via submit_map. */
  solveOnHost?: boolean | null;
}

/** Upload a client-solved OutputMap (phone-side final solve, wasm). The
 * server persists it as if it had solved it and replies result_ready. */
export interface SubmitMapMessage {
  type: "submit_map";
  map: OutputMap;
}

export interface DetectionsMessage {
  type: "detections";
  batch: DetectionRecord[];
}

/** One inertial sample, CAMERA frame (+X right, +Y up, -Z look) — the
 * client applies its device-specific DeviceMotion axis mapping. */
export interface ImuSample {
  /** Phone monotonic clock, ms — same domain as tCaptureMs. */
  t: number;
  /** Angular rate [x, y, z], rad/s. */
  gyro: Vec3;
  /** Specific force (a − g) [x, y, z], m/s². */
  accel: Vec3;
}

/** IMU batch for the WebXR-free capture path: dead reckoning between
 * frames + metric scale + gravity for the joint pose+LED solve. */
export interface ImuBatchMessage {
  type: "imu_batch";
  samples: ImuSample[];
}

/** Camera/exposure telemetry (§7.1 exposure_report). The web client cannot
 * read the real 3A/ISP state (WebXR exposes only the camera texture), so these
 * are software estimates; iso/exposureTimeMs are reserved for clients that can. */
export interface ExposureStats {
  /** Phone monotonic clock at the end of the measurement window, ms. */
  tCaptureMs: number;
  /** Median camera frame interval, ms — the shutter-speed proxy. */
  frameIntervalMs: number;
  /** Mean scene luminance [0,1], unthresholded downsampled frame. */
  meanLuma: number;
  /** 95th-percentile scene luminance [0,1]. */
  p95Luma: number;
  /** Fraction of pixels at/above 0.98 (saturated highlights). */
  clipFrac: number;
  /** Median detector blobs per frame at the current threshold. */
  blobCount: number;
  /** Detector luminance threshold in effect. */
  detectorThreshold: number;
  /** Real sensor ISO from the 3A/ISP, when the platform exposes it. */
  iso?: number | null;
  /** Real sensor exposure time (ms), when the platform exposes it. */
  exposureTimeMs?: number | null;
  /** WebXR light-estimation primary intensity (max RGB, relative units). */
  ambientIntensity?: number | null;
}

export interface ExposureReportMessage {
  type: "exposure_report";
  report: ExposureStats;
}

export interface GetStatusMessage {
  type: "get_status";
}

/** Sent by pattern followers (e.g. the virtual LED wall) to poll the pattern clock. */
export interface GetPatternMessage {
  type: "get_pattern";
}

/** Poll the continuous solver for the latest interim reconstruction. */
export interface GetLiveMapMessage {
  type: "get_live_map";
}

/** Poll the FINAL solve's progress while the stop_mapping reply is pending. */
export interface GetSolveStatusMessage {
  type: "get_solve_status";
}

/** A contiguous run of same-color LEDs in a counting pattern. */
export interface ColorBlock {
  start: number;
  count: number;
  /** Block color [r, g, b] in [0,1]. */
  rgb: Vec3;
}

/** LED-counting handshake (§7.9): display a static color-block pattern.
 * Blocks paint [start, start+count); uncovered LEDs are off; painting past
 * the physical strip end IS the probe (the phone binary-searches the length
 * by observing which blocks light). Empty blocks = all off. Reply:
 * counting_state. */
export interface SetCountingPatternMessage {
  type: "set_counting_pattern";
  blocks: ColorBlock[];
  /** Player output channel; null/omitted -> 0. */
  channel?: number | null;
}

/** Persist the detected strip length for a channel (defaults future
 * codeParams.ledCount, bounds playback buffers). Reply: led_count_state. */
export interface SetLedCountMessage {
  type: "set_led_count";
  ledCount: number;
  /** Player output channel; null/omitted -> 0. */
  channel?: number | null;
}

/** Upload the skeletonized topology for a stored map (Phase F). The player
 * persists it next to the map and replies result_ready (mirrors submit_map). */
export interface SubmitTopologyMessage {
  type: "submit_topology";
  topology: Topology;
}

/** Playback control (§7.8): select the effect and overlay params. 'off' is
 * universal; other effects are player-capability-dependent (reply: error
 * code='unsupported_effect' when not shipped). Reply: playback_state. */
export interface SetPlaybackMessage {
  type: "set_playback";
  effect: string;
  params?: PlaybackParams | null;
  /** Stored map/topology to play on; null keeps the current selection. */
  mapId?: string | null;
}

/** Poll the current playback state. Reply: playback_state. */
export interface GetPlaybackMessage {
  type: "get_playback";
}

/** Drain the player's rendered-frame timing log (the phone forwards it to
 * the trace server to diagnose pattern-generator stutter). Reply:
 * frame_timing. */
export interface GetFrameTimingMessage {
  type: "get_frame_timing";
}

/** Pull the player's stored map+topology as a MappingBundle, streamed in
 * chunks (bytes [offset, offset+maxLen)). Reply: stored_map_chunk. */
export interface GetStoredMapMessage {
  type: "get_stored_map";
  offset: number;
  maxLen: number;
}

export type ClientMessage =
  | HelloMessage
  | TimeSyncPingMessage
  | StartMappingMessage
  | ConfigureMessage
  | StopMappingMessage
  | SubmitMapMessage
  | DetectionsMessage
  | ImuBatchMessage
  | ExposureReportMessage
  | GetStatusMessage
  | GetPatternMessage
  | GetLiveMapMessage
  | GetSolveStatusMessage
  | SetCountingPatternMessage
  | SetLedCountMessage
  | SubmitTopologyMessage
  | SetPlaybackMessage
  | GetPlaybackMessage
  | GetFrameTimingMessage
  | GetStoredMapMessage;

// ---------------------------------------------------------------------------
// Server -> Client messages (§7.2)
// ---------------------------------------------------------------------------

export interface WelcomeMessage {
  type: "welcome";
  sessionId: string;
  codeParams: CodeParams;
  /** Host score on the canned solver benchmark (ms), for the client's
   * solver-placement decision; null while still measuring. */
  solverBenchMs: number | null;
  /** Stable hardware MAC (same address the BLE advertisement uses),
   * colon-separated uppercase hex. Empty on older firmware. */
  mac: string;
  /** Current display / Bluetooth name (default "Led Widget <6-hex>" or a
   * user-customized name). Empty on older firmware. */
  deviceName: string;
  /** Git commit the firmware was built from (full 40-char hash), stamped
   * in via Bazel --stamp. Empty on older firmware / an unstamped build. */
  fwGitCommit: string;
  /** Whether the firmware was built from a dirty working tree. */
  fwGitDirty: boolean;
  /** Release version from the nearest firmware-v* tag (e.g. "1.2.0",
   * or "0.0.0-dev"), stamped in via Bazel --stamp. Empty on older
   * firmware / an unstamped build. */
  fwVersion: string;
}

/** Reply to stop_mapping with solveOnHost=false: capture stopped + log
 * persisted, no host solve. The counts echo what the server logged. */
export interface MappingStoppedMessage {
  type: "mapping_stopped";
  detections: number;
  imuSamples: number;
}

export interface TimeSyncPongMessage {
  type: "time_sync_pong";
  /** Echoed phone clock at original send, in milliseconds. */
  t0: number;
  /** Server clock at receive of ping, in milliseconds. */
  t1: number;
  /** Server clock at send of pong, in milliseconds. */
  t2: number;
}

export interface MappingStartedMessage {
  type: "mapping_started";
  /** Server-clock time of the start of a known cycle, in milliseconds. */
  patternClockEpoch: number;
  codeParams: CodeParams;
}

export interface StatusMessage {
  type: "status";
  identified: number;
  total: number;
  lowParallax: number;
}

/** Reply to get_pattern: the pattern clock a follower should render against. */
export interface PatternStateMessage {
  type: "pattern_state";
  active: boolean;
  /** Server-clock start of a known cycle (ms); null when no capture is active. */
  patternClockEpoch: number | null;
  codeParams: CodeParams;
}

/** Reply to get_live_map: latest interim reconstruction; null before the first solve or when idle. */
export interface LiveMapMessage {
  type: "live_map";
  active: boolean;
  map: OutputMap | null;
}

/** Interim LED position during a running solve (lightweight preview). */
export interface SolveLed {
  id: number;
  xyz: Vec3;
}

/** Reply to get_solve_status: the final solve's live state. All-null
 * fields when no solve is running or it reports no progress. */
export interface SolveStatusMessage {
  type: "solve_status";
  running: boolean;
  /** Estimated optimizer progress [0,1] (eval budget consumed). */
  progress: number | null;
  rmsPx: number | null;
  leds: SolveLed[] | null;
  /** Decimated solved camera path, same gauge as leds. */
  trajectory: Vec3[] | null;
}

export interface ResultReadyMessage {
  type: "result_ready";
  mapId: string;
}

export interface ErrorMessage {
  type: "error";
  code: string;
  message: string;
}

/** Reply to set_counting_pattern: whether a counting pattern is displayed
 * and the server-clock time it latched (the phone's read-valid time). */
export interface CountingStateMessage {
  type: "counting_state";
  active: boolean;
  /** Server-clock time the pattern took effect (ms); null when inactive. */
  epochMs: number | null;
}

/** Reply to set_led_count: echo of the persisted per-channel strip length. */
export interface LedCountStateMessage {
  type: "led_count_state";
  ledCount: number;
  channel: number;
}

/** Reply to set_playback / get_playback: the effective configuration (the
 * player echoes what it actually runs, defaults filled into params). */
export interface PlaybackStateMessage {
  type: "playback_state";
  active: boolean;
  /** The running effect; "off" when inactive. */
  effect: string;
  params: PlaybackParams | null;
  /** The stored map/topology playback runs on; null when none selected. */
  mapId: string | null;
}

/** One rendered mapping-pattern frame: the player's monotonic-clock time
 * (MICROSECONDS, raw micros()) at which it pushed absolute frame `seq`
 * (frames since the pattern epoch, before the cycle modulo) to the LEDs.
 * Integer µs — the firmware is a single-precision-only RISC-V core. */
export interface FrameTick {
  seq: number;
  tMonoUs: number;
}

/** Reply to get_frame_timing: a drained batch of rendered-frame timestamps
 * plus the count dropped to ring-buffer overflow since the last poll. Even
 * bitPeriodUs spacing between successive tMonoUs = smooth generation; gaps =
 * the pattern render loop stalled. patternClockEpochMs is null when idle.
 * All-integer (µs/ms): firmware->phone only, so no double on that path. */
export interface FrameTimingMessage {
  type: "frame_timing";
  patternClockEpochMs: number | null;
  bitPeriodUs: number;
  cycleFrames: number;
  dropped: number;
  ticks: FrameTick[];
}

/** Reply to get_stored_map: a slice of the encoded MappingBundle. `data` is
 * base64; the phone loops until it has `totalLen` bytes, then decodes. */
export interface StoredMapChunkMessage {
  type: "stored_map_chunk";
  totalLen: number;
  offset: number;
  /** Base64-encoded bytes [offset, offset+len) of the MappingBundle. */
  data: string;
  hasTopology: boolean;
}

export type ServerMessage =
  | WelcomeMessage
  | TimeSyncPongMessage
  | MappingStartedMessage
  | MappingStoppedMessage
  | StatusMessage
  | PatternStateMessage
  | LiveMapMessage
  | SolveStatusMessage
  | ResultReadyMessage
  | ErrorMessage
  | CountingStateMessage
  | LedCountStateMessage
  | PlaybackStateMessage
  | FrameTimingMessage
  | StoredMapChunkMessage;
